{"command": "cat > /app/solve_reflow.py <<'PY'
import os, json, math
import pandas as pd

DATA='/app/data'
OUT='/app/output'
os.makedirs(OUT, exist_ok=True)

runs=pd.read_csv(f'{DATA}/mes_log.csv', dtype={'run_id':str})
tc=pd.read_csv(f'{DATA}/thermocouples.csv', dtype={'run_id':str,'tc_id':str})
defects=pd.read_csv(f'{DATA}/test_defects.csv', dtype={'run_id':str})

runs=runs.sort_values('run_id', kind='mergesort')
tc=tc.sort_values(['run_id','tc_id','time_s'], kind='mergesort')

RAMP_LIMIT=2.0
PREHEAT_MIN=100.0
PREHEAT_MAX=150.0
TAL_MIN=30.0
TAL_MAX=60.0
PEAK_MARGIN=20.0


def r2(x):
    if x is None or pd.isna(x) or math.isinf(float(x)):
        return None
    return round(float(x),2)


def max_slope_in_band(df, tmin, tmax):
    best=None
    arr=df.sort_values('time_s')[['time_s','temp_c']].to_numpy(float)
    for i in range(1,len(arr)):
        t0,y0=arr[i-1]
        t1,y1=arr[i]
        dt=t1-t0
        if dt<=0:
            continue
        if tmin<=y0<=tmax and tmin<=y1<=tmax:
            s=(y1-y0)/dt
            best=s if best is None else max(best,s)
    return best


def time_above(df,thr):
    total=0.0
    arr=df.sort_values('time_s')[['time_s','temp_c']].to_numpy(float)
    for i in range(1,len(arr)):
        t0,y0=arr[i-1]
        t1,y1=arr[i]
        if t1<=t0:
            continue
        if y0>thr and y1>thr:
            total += t1-t0
        else:
            crosses=((y0<=thr<y1) or (y1<=thr<y0)) and y1!=y0
            if crosses:
                frac=(thr-y0)/(y1-y0)
                tcross=t0+frac*(t1-t0)
                if y0<=thr and y1>thr:
                    total += t1-tcross
                else:
                    total += tcross-t0
    return total

# Q1
max_ramp_by_run={}
violating=[]
for run_id,g_run in tc.groupby('run_id', sort=True):
    vals=[]
    for tc_id,g_tc in g_run.groupby('tc_id', sort=True):
        slope=max_slope_in_band(g_tc, PREHEAT_MIN, PREHEAT_MAX)
        if slope is not None:
            vals.append((slope, tc_id))
    if vals:
        slope,tc_id=max(vals, key=lambda x:(x[0], -int(''.join(filter(str.isdigit,x[1])) or 0)))
        slope=r2(slope)
        max_ramp_by_run[run_id]={"tc_id":tc_id,"max_preheat_ramp_c_per_s":slope}
        if slope is not None and slope>RAMP_LIMIT:
            violating.append(run_id)
    else:
        max_ramp_by_run[run_id]={"tc_id":None,"max_preheat_ramp_c_per_s":None}
        violating.append(run_id)

q1={
    'ramp_rate_limit_c_per_s':RAMP_LIMIT,
    'violating_runs':sorted(violating),
    'max_ramp_by_run':dict(sorted(max_ramp_by_run.items()))
}

# Q2
q2=[]
for _,run in runs.iterrows():
    run_id=run.run_id
    thr=float(run.solder_liquidus_c)
    vals=[]
    g_run=tc[tc.run_id==run_id]
    for tc_id,g_tc in g_run.groupby('tc_id', sort=True):
        if len(g_tc)<2:
            continue
        tal=time_above(g_tc,thr)
        peak=g_tc.temp_c.max()
        vals.append((tal,peak,tc_id))
    if vals:
        tal,peak,tc_id=min(vals, key=lambda x:(x[0],x[1],x[2]))
        status='compliant' if TAL_MIN<=tal<=TAL_MAX else 'non-compliant'
        q2.append({
            'run_id':run_id,
            'tc_id':tc_id,
            'tal_s':r2(tal),
            'required_min_tal_s':TAL_MIN,
            'required_max_tal_s':TAL_MAX,
            'status':status
        })
    else:
        q2.append({
            'run_id':run_id,
            'tc_id':None,
            'tal_s':None,
            'required_min_tal_s':TAL_MIN,
            'required_max_tal_s':TAL_MAX,
            'status':'non-compliant'
        })
q2=sorted(q2,key=lambda x:x['run_id'])

# Q3
min_peak_by_run={}
failing=[]
for _,run in runs.iterrows():
    run_id=run.run_id
    req=float(run.solder_liquidus_c)+PEAK_MARGIN
    vals=[]
    g_run=tc[tc.run_id==run_id]
    for tc_id,g_tc in g_run.groupby('tc_id', sort=True):
        vals.append((float(g_tc.temp_c.max()), tc_id))
    if vals:
        peak,tc_id=min(vals, key=lambda x:(x[0],x[1]))
        if peak<req:
            failing.append(run_id)
        min_peak_by_run[run_id]={
            'tc_id':tc_id,
            'peak_temp_c':r2(peak),
            'required_min_peak_c':r2(req)
        }
    else:
        failing.append(run_id)
        min_peak_by_run[run_id]={
            'tc_id':None,
            'peak_temp_c':None,
            'required_min_peak_c':r2(req)
        }
q3={'failing_runs':sorted(failing),'min_peak_by_run':dict(sorted(min_peak_by_run.items()))}

# Q4
q4=[]
for _,r in runs.iterrows():
    req=(r.boards_per_min * r.board_length_cm) / r.loading_factor
    actual=float(r.conveyor_speed_cm_min)
    q4.append({
        'run_id':r.run_id,
        'required_min_speed_cm_min':r2(req),
        'actual_speed_cm_min':r2(actual),
        'meets': bool(actual>=req)
    })
q4=sorted(q4,key=lambda x:x['run_id'])

# Q5
# aggregate defects
agg=defects.groupby('run_id')['count'].sum().to_dict()
q2map={x['run_id']:x['status'] for x in q2}
q3fail=set(failing)

out=[]
for fam,g in runs.groupby('board_family', sort=True):
    scored=[]
    for _,r in g.iterrows():
        rid=r.run_id
        compliant=(q2map.get(rid)=='compliant' and rid not in q3fail)
        defects_total=int(agg.get(rid,0))
        speed=float(r.conveyor_speed_cm_min)
        downtime=float(r.downtime_s)
        scored.append((0 if compliant else 1, defects_total, downtime, -speed, rid))
    scored=sorted(scored)
    best=scored[0][-1]
    runners=sorted([x[-1] for x in scored[1:]])
    out.append({'board_family':fam,'best_run_id':best,'runner_up_run_ids':runners})
q5=sorted(out,key=lambda x:x['board_family'])

for name,obj in [('q01',q1),('q02',q2),('q03',q3),('q04',q4),('q05',q5)]:
    with open(f'{OUT}/{name}.json','w') as f:
        json.dump(obj,f,indent=2)

# validate
for i in range(1,6):
    p=f'{OUT}/q0{i}.json'
    with open(p) as f:
        json.load(f)
print('validated')
PY
python3 /app/solve_reflow.py && for f in /app/output/q0*.json; do echo ===$f===; head -20 $f; done", "summary": "Create solver script and generate all required JSON outputs", "security_risk": "MEDIUM", "timeout": 300}

{"command": "bash -lc 'cat > /app/solve_reflow.py <<"PY"
import os, json, math
import pandas as pd
DATA="/app/data"
OUT="/app/output"
os.makedirs(OUT, exist_ok=True)
runs=pd.read_csv(f"{DATA}/mes_log.csv", dtype={"run_id":str}).sort_values("run_id", kind="mergesort")
tc=pd.read_csv(f"{DATA}/thermocouples.csv", dtype={"run_id":str,"tc_id":str}).sort_values(["run_id","tc_id","time_s"], kind="mergesort")
defects=pd.read_csv(f"{DATA}/test_defects.csv", dtype={"run_id":str})
RAMP_LIMIT=2.0
PREHEAT_MIN=100.0
PREHEAT_MAX=150.0
TAL_MIN=30.0
TAL_MAX=60.0
PEAK_MARGIN=20.0

def r2(x):
    if x is None: return None
    x=float(x)
    return None if math.isnan(x) or math.isinf(x) else round(x,2)

def max_slope(df,tmin,tmax):
    a=df[["time_s","temp_c"]].to_numpy(float)
    best=None
    for i in range(1,len(a)):
        dt=a[i][0]-a[i-1][0]
        if dt<=0: continue
        if tmin<=a[i-1][1]<=tmax and tmin<=a[i][1]<=tmax:
            s=(a[i][1]-a[i-1][1])/dt
            best=s if best is None else max(best,s)
    return best

def tal(df,thr):
    a=df[["time_s","temp_c"]].to_numpy(float)
    total=0.0
    for i in range(1,len(a)):
        t0,y0=a[i-1]; t1,y1=a[i]
        if t1<=t0: continue
        if y0>thr and y1>thr:
            total += t1-t0
        elif ((y0<=thr<y1) or (y1<=thr<y0)) and y1!=y0:
            frac=(thr-y0)/(y1-y0)
            tc=t0+frac*(t1-t0)
            total += (t1-tc) if y0<=thr<y1 else (tc-t0)
    return total

q1={"ramp_rate_limit_c_per_s":RAMP_LIMIT,"violating_runs":[],"max_ramp_by_run":{}}
q2=[]
q3={"failing_runs":[],"min_peak_by_run":{}}
q4=[]
for _,r in runs.iterrows():
    rid=str(r.run_id)
    gr=tc[tc.run_id==rid]
    ramps=[]; tals=[]; peaks=[]
    for tcid,gtc in gr.groupby("tc_id", sort=True):
        ms=max_slope(gtc,PREHEAT_MIN,PREHEAT_MAX)
        if ms is not None: ramps.append((ms,str(tcid)))
        if len(gtc)>=2:
            tals.append((tal(gtc,float(r.solder_liquidus_c)), float(gtc.temp_c.max()), str(tcid)))
        peaks.append((float(gtc.temp_c.max()), str(tcid)))
    if ramps:
        rs,rt=sorted(ramps,key=lambda x:(-x[0],x[1]))[0]
        q1["max_ramp_by_run"][rid]={"tc_id":rt,"max_preheat_ramp_c_per_s":r2(rs)}
        if rs>RAMP_LIMIT: q1["violating_runs"].append(rid)
    else:
        q1["max_ramp_by_run"][rid]={"tc_id":None,"max_preheat_ramp_c_per_s":None}
        q1["violating_runs"].append(rid)
    if tals:
        tv,pv,tt=min(tals,key=lambda x:(x[0],x[1],x[2]))
        st="compliant" if TAL_MIN<=tv<=TAL_MAX else "non-compliant"
        q2.append({"run_id":rid,"tc_id":tt,"tal_s":r2(tv),"required_min_tal_s":TAL_MIN,"required_max_tal_s":TAL_MAX,"status":st})
    else:
        q2.append({"run_id":rid,"tc_id":None,"tal_s":None,"required_min_tal_s":TAL_MIN,"required_max_tal_s":TAL_MAX,"status":"non-compliant"})
    req=float(r.solder_liquidus_c)+PEAK_MARGIN
    if peaks:
        pk,pt=min(peaks,key=lambda x:(x[0],x[1]))
        q3["min_peak_by_run"][rid]={"tc_id":pt,"peak_temp_c":r2(pk),"required_min_peak_c":r2(req)}
        if pk<req: q3["failing_runs"].append(rid)
    else:
        q3["min_peak_by_run"][rid]={"tc_id":None,"peak_temp_c":None,"required_min_peak_c":r2(req)}
        q3["failing_runs"].append(rid)
    minspeed=(float(r.boards_per_min)*float(r.board_length_cm))/float(r.loading_factor)
    actual=float(r.conveyor_speed_cm_min)
    q4.append({"run_id":rid,"required_min_speed_cm_min":r2(minspeed),"actual_speed_cm_min":r2(actual),"meets":actual>=minspeed})
q1["violating_runs"]=sorted(q1["violating_runs"])
q2=sorted(q2,key=lambda x:x["run_id"])
q3["failing_runs"]=sorted(q3["failing_runs"])
q4=sorted(q4,key=lambda x:x["run_id"])
defsum=defects.groupby("run_id")["count"].sum().to_dict()
q2s={x["run_id"]:x["status"] for x in q2}
q5=[]
for fam,g in runs.groupby("board_family", sort=True):
    scores=[]
    for _,r in g.iterrows():
        rid=str(r.run_id)
        scores.append(((0 if q2s[rid]=="compliant" and rid not in q3["failing_runs"] else 1), int(defsum.get(rid,0)), float(r.downtime_s), -float(r.conveyor_speed_cm_min), rid))
    scores.sort()
    q5.append({"board_family":str(fam),"best_run_id":scores[0][-1],"runner_up_run_ids":sorted(x[-1] for x in scores[1:])})
for name,obj in [("q01.json",q1),("q02.json",q2),("q03.json",q3),("q04.json",q4),("q05.json",sorted(q5,key=lambda x:x["board_family"]))]:
    with open(f"{OUT}/{name}","w") as f: json.dump(obj,f,indent=2)
for i in range(1,6):
    with open(f"{OUT}/q0{i}.json") as f: json.load(f)
print("validated")
